import { Tex, rgb, scale, sprite, outline, mix, rngFor, speckle } from './pixel.js';
import { T, F, paint } from './texreg.js';
import { WOOD_COLORS } from './tex_wood.js';
import { DYE_HEX, WOOL_COLORS } from './tex_colored.js';

const I = (name, fn) => T('item:' + name, fn);
const FI = (re, fn) => F(new RegExp('^item:' + re.source.slice(1)), fn);

