  wooden: ['#3c2a14', '#684e1e', '#896727', '#a88543', '#c29d62'],
  stone: ['#3a3a3a', '#545454', '#6f6f6f', '#8a8a8a', '#a4a4a4'],
  iron: ['#444444', '#828282', '#c3c3c3', '#d8d8d8', '#ffffff'],
  golden: ['#4a2f05', '#b27c0e', '#eacb2c', '#fdf55f', '#ffffb5'],
  diamond: ['#0c3d3a', '#13827c', '#2bc7ac', '#4aedd9', '#a1fbe8'],
  netherite: ['#1b1517', '#2d2427', '#433d40', '#5a5156', '#776e72'],
  leather: ['#3b2010', '#6b3c1e', '#8f5530', '#a66a40', '#c08758'],
