const STICK = { s: '#5d4527', S: '#896727', K: '#3c2a14' };

function matPal(m, extra = {}) {
  const c = MAT[m];
  return { 0: c[0], 1: c[1], 2: c[2], 3: c[3], 4: c[4], ...STICK, ...extra };
}

