      const rows = ARMOR_SHAPES[p].map((r) => r.replace(/ /g, '1'));
      const t = sprite(rows, matPal(m));
      if (m === 'chainmail') for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) if (t.alpha(x, y) && (x + y) % 2 === 0 && t.get(x, y)[0] > 70) t.set(x, y, rgb('#3a3a3a'));
