for (const w of Object.keys(WOOD_COLORS)) {
  I(`${w}_door`, () => {
    const top = paint(`${w}_door_top`), bot = paint(`${w}_door_bottom`);
    const t = new Tex();
    for (let y = 0; y < 8; y++) for (let x = 0; x < 8; x++) { t.set(x + 4, y, top.get(x * 2, y * 2)); t.set(x + 4, y + 8, bot.get(x * 2, y * 2)); }
    return t;
  });
  I(`${w}_sign`, () => {
    const c = WOOD_COLORS[w].planks;
    return sprite(['', '', '.00000000000000.', '.0pppppppppppp0.', '.0pPPPPPPPPPPp0.', '.0pppppppppppp0.', '.0pPPPPPPPPPPp0.', '.0pppppppppppp0.', '.00000000000000.', '.......ss.......', '.......ss.......', '.......ss.......', '.......ss.......', '.......ss.......'], { 0: scale(rgb(c), 0.5), p: rgb(c), P: scale(rgb(c), 0.7), s: '#5d4527' });
  });
}
